#!/usr/bin/env bash
# generated by grippd 0.3.0 from grippd.yaml. Don't edit: change grippd.yaml and grippd regenerates this file.
# Usage: mint.sh <job>     job: checks or ship
# Swaps this job's GitHub OIDC token for a one-use key. grippd binds it to this commit,
# workflow, run and attempt, and gives each job of a run one key, once. The key can do
# only what the run's manifest lists: grippd compiles that from the push's diff (never
# from anything this runner says) and checks every later call against it. It expires
# with the job. Keys that deploy, migrate or change infrastructure are never minted to CI.
set -euo pipefail
job=$1
case $job in
  checks) kind=cache env=ci ;;
  # Ship run by hand ships to dev; a push to main ships to staging; a pull request's Preview
  # ships to pr-<number>. grippd checks this against the run's own OIDC claims, so saying
  # otherwise gets nothing.
  ship)
    kind=upload
    case $GITHUB_EVENT_NAME in
      workflow_dispatch) env=dev ;;
      pull_request) n=${GITHUB_REF#refs/pull/}; env=pr-${n%/merge} ;;
      *) env=staging ;;
    esac
    ;;
  *) echo "usage: mint.sh checks|ship" >&2; exit 2 ;;
esac
oidc=$(curl -fsS -H "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
  "$ACTIONS_ID_TOKEN_REQUEST_URL&audience=https://api.grippd.sh" | jq -r .value)
resp=$(mktemp)
code=$(curl -sS -o "$resp" -w '%{http_code}' -X POST "https://grippd-api.grippd.workers.dev/v1/projects/$GRIPPD_PROJECT/keys" \
  -H "Authorization: Bearer $oidc" -H "Content-Type: application/json" \
  -d "$(jq -n --arg job "$job" --arg kind "$kind" --arg env "$env" \
    '{app: "repo", env: $env, job: $kind, ci_job: $job, ttl: "15m"}')")
if [[ $code != 2* ]]; then
  # grippd says what it expected, what was asked for and why; show it on the run.
  msg=$(jq -r '(.error | if type == "object" then .message else . end) // .message // empty' "$resp" 2>/dev/null || true)
  echo "::error title=grippd refused this job's key::${msg:-HTTP $code}"
  { echo "### grippd refused this job's key"; echo; echo "${msg:-HTTP $code}"; } >> "$GITHUB_STEP_SUMMARY"
  exit 1
fi
# The variables this job needs: GRIPPD_UPLOAD_TOKEN for uploads, TURBO_TOKEN and
# TURBO_REMOTE_CACHE_SIGNATURE_KEY for the Turborepo cache.
while IFS='=' read -r k v; do
  echo "::add-mask::$v"
  echo "$k=$v" >> "$GITHUB_ENV"
done < <(jq -r '.env | to_entries[] | "\(.key)=\(.value)"' "$resp")
echo "Minted the $job key; expires $(jq -r .expires_at "$resp")"
if jq -e '.manifest' "$resp" >/dev/null; then
  manifest="$RUNNER_TEMP/grippd-manifest.json"
  jq '.manifest' "$resp" > "$manifest"
  echo "GRIPPD_MANIFEST=$manifest" >> "$GITHUB_ENV"
  # A run that may only read the cache doesn't try to write it.
  if [[ $(jq -r '.cache.write // empty' "$manifest") == "" ]]; then
    echo "TURBO_CACHE=local:rw,remote:r" >> "$GITHUB_ENV"
  fi
  echo "Slot: $(jq -r '.slot // "none (no uploads)"' "$manifest"). Uploads: $(jq -r '[.artifacts[].name] | if length == 0 then "none" else join(", ") end' "$manifest")"
  jq -r '.why[] | "  - " + .' "$manifest"
elif [[ $job == ship ]]; then
  echo "::error title=grippd sent no manifest::the ship job builds what grippd's manifest lists, and grippd sent none"
  exit 1
fi
